31|    /**
32|     * Create a user with a real Sanctum token bearing specific abilities.
33|     * Optionally assign Spatie permissions so role_or_permission middleware passes.
34|     */
35|    private function createTokenWithAbilities(array $abilities, array $permissions = []): string
36|    {
37|        $args = [];
38|        if ($permissions) {
39|            $args['permissions'] = $permissions;
40|        }
41|        ['user' => $user] = $this->createUserWithUnit(...$args);
42|
43|        return $user->createToken('test-token', $abilities)->plainTextToken;
44|    }
45|
46|    private function apiGet(string $url, string $token): TestResponse
47|    {
48|        return $this->withHeaders([
49|            'Authorization' => 'Bearer '.$token,
50|            'Accept' => 'application/json',
51|        ])->getJson($url);
52|    }
53|
54|    private function apiPost(string $url, array $data, string $token): TestResponse
55|    {
56|        return $this->withHeaders([
57|            'Authorization' => 'Bearer '.$token,
58|            'Accept' => 'application/json',
59|            'Content-Type' => 'application/json',
60|        ])->postJson($url, $data);
61|    }
