440|    /**
441|     * Get the raw abilities array from a user's login token by hitting /api/login.
442|     * Returns the token string; decode it to inspect abilities if needed.
443|     */
444|    private function loginAndGetToken(string $nCode, string $password = 'password'): string
445|    {
446|        $response = $this->postJson('/api/login', [
447|            'n_code' => $nCode,
448|            'password' => $password,
449|        ]);
450|        $response->assertOk();
451|
452|        return $response->json('token');
453|    }
