455|    /**
456|     * Decode a Sanctum token's abilities by looking up the PersonalAccessToken.
457|     * This avoids JWT parsing and uses Laravel's token storage directly.
458|     */
459|    private function getTokenAbilities(string $token): array
460|    {
461|        $plain = PersonalAccessToken::findToken($token);
462|
463|        return $plain?->abilities ?? [];
464|    }
