4|
5|use App\Services\Zabbix\ServiceZabbixClient;
6|use App\Services\Zabbix\ZabbixClient;
7|use App\Services\Zabbix\ZabbixResult;
8|use App\Services\ZabbixService;
9|use Illuminate\Http\Client\ConnectionException;
10|use RuntimeException;
11|use Tests\TestCase;
12|use Throwable;
13|
14|covers(ServiceZabbixClient::class);
15|covers(ZabbixResult::class);
16|
17|/**
18| * #741: the connection layer is a typed value, testable without a Zabbix
19| * server. Every scenario below runs against an in-memory stub service —
20| * outage, timeout and invalid response included.
21| */
22|class ZabbixAdapterTest extends TestCase
23|{
24|    /**
25|     * A ZabbixService that throws the given exception instead of talking
26|     * to anything (overrides both methods the adapter calls).
27|     */
28|    private function throwingService(Throwable $e): ZabbixService
29|    {
30|        return new class($e) extends ZabbixService
31|        {
32|            public function __construct(private readonly Throwable $e) {}
33|
34|            public function getInterfaceTraffic($itemId, $duration = 3600)
35|            {
36|                throw $this->e;
37|            }
38|
39|            public function getLatestValues(array $itemIds): array
40|            {
41|                throw $this->e;
42|            }
43|        };
44|    }
45|
46|    private function workingService(): ZabbixService
47|    {
48|        return new class extends ZabbixService
49|        {
50|            public function __construct() {}
51|
52|            public function getInterfaceTraffic($itemId, $duration = 3600)
53|            {
54|                return [['x' => 1, 'y' => 2.5]];
55|            }
56|
57|            public function getLatestValues(array $itemIds): array
58|            {
59|                return ['100' => 1.5, '200' => null];
60|            }
61|        };
62|    }
63|
64|    public function test_success_wraps_the_payload(): void
65|    {
66|        $client = new ServiceZabbixClient($this->workingService());
67|
68|        $traffic = $client->traffic(100, 3600);
69|        $this->assertTrue($traffic->isOk());
70|        $this->assertFalse($traffic->failed());
71|        $this->assertSame([['x' => 1, 'y' => 2.5]], $traffic->data());
72|        $this->assertNull($traffic->failure());
73|
74|        $latest = $client->latestValues(['100', '200']);
75|        $this->assertTrue($latest->isOk());
76|        $this->assertSame(['100' => 1.5, '200' => null], $latest->data());
77|    }
78|
79|    public function test_timeout_is_classified_as_timeout(): void
80|    {
81|        $client = new ServiceZabbixClient($this->throwingService(
82|            new ConnectionException('cURL error 28: Operation timed out after 10001 milliseconds with 0 bytes received')
83|        ));
84|
85|        $result = $client->traffic(100);
86|
87|        $this->assertTrue($result->failed());
88|        $this->assertSame('timeout', $result->failure());
89|        $this->assertNull($result->data());
90|        $this->assertStringContainsString('timed out', $result->message());
91|    }
92|
93|    public function test_connection_refused_is_classified_as_connection(): void
94|    {
95|        $client = new ServiceZabbixClient($this->throwingService(
96|            new ConnectionException('cURL error 7: Failed to connect to 127.0.0.1 port 9000: Connection refused')
97|        ));
98|
99|        $result = $client->latestValues(['100']);
100|
101|        $this->assertTrue($result->failed());
102|        $this->assertSame('connection', $result->failure());
103|    }
104|
105|    public function test_http_error_status_is_classified_as_connection(): void
106|    {
107|        // What ZabbixService throws for a non-2xx API response.
108|        $client = new ServiceZabbixClient($this->throwingService(
109|            new RuntimeException('Zabbix API HTTP error: 503')
110|        ));
111|
112|        $this->assertSame('connection', $client->traffic(100)->failure());
113|    }
114|
115|    public function test_invalid_json_is_classified_as_invalid_response(): void
116|    {
117|        // What ZabbixService throws when the body is not JSON at all.
118|        $client = new ServiceZabbixClient($this->throwingService(
119|            new RuntimeException('Zabbix API returned invalid JSON')
120|        ));
121|
122|        $result = $client->latestValues(['100']);
123|
124|        $this->assertTrue($result->failed());
125|        $this->assertSame('invalid_response', $result->failure());
126|    }
127|
128|    public function test_unexpected_errors_fall_back_to_error(): void
129|    {
130|        $client = new ServiceZabbixClient($this->throwingService(
131|            new RuntimeException('something else entirely')
132|        ));
133|
134|        $this->assertSame('error', $client->traffic(100)->failure());
135|    }
136|
137|    public function test_a_stub_client_satisfies_the_interface_contract(): void
138|    {
139|        // The shape controllers rely on: a stub can produce both outcomes
140|        // with no server, which is the whole point of the extraction (#741).
141|        $stub = new class implements ZabbixClient
142|        {
143|            public function traffic(int|string $itemId, int $duration = 3600): ZabbixResult
144|            {
145|                return ZabbixResult::fail('timeout', 'stub timeout');
146|            }
147|
148|            public function latestValues(array $itemIds): ZabbixResult
149|            {
150|                return ZabbixResult::success(['100' => 42.0]);
151|            }
152|        };
153|
154|        $this->assertTrue($stub->traffic(1)->failed());
155|        $this->assertSame('timeout', $stub->traffic(1)->failure());
156|        $this->assertSame(['100' => 42.0], $stub->latestValues(['100'])->data());
157|    }
