2|
3|namespace App\Services;
4|
5|use Illuminate\Support\Facades\Http;
6|
7|class ZabbixService
8|{
9|    protected string $url;
10|
11|    protected string $auth;
12|
13|    public function __construct()
14|    {
15|        $this->url = config('services.zabbix.url');
16|        $this->auth = config('services.zabbix.token');
17|    }
18|
19|    public function getInterfaceTraffic($itemId, $duration = 3600) // <-- پارامتر جدید
20|    {
21|        $now = time();
22|        $timeFrom = $now - $duration; // استفاده از duration
23|
24|        $response = $this->request('history.get', [
25|            'output' => 'extend',
26|            'history' => 3,
27|            'itemids' => $itemId,
28|            'sortfield' => 'clock',
29|            'sortorder' => 'ASC',
30|            'time_from' => $timeFrom,
31|            'time_till' => $now,
32|        ]);
33|
34|        if (! isset($response['result'])) {
35|            return [];
36|        }
37|
38|        $history = collect($response['result']);
39|        $points = [];
40|
41|        for ($i = 1; $i < $history->count(); $i++) {
42|            $prev = $history[$i - 1];
43|            $curr = $history[$i];
44|
45|            $timeDiff = $curr['clock'] - $prev['clock'];
46|            $valueDiff = $curr['value'] - $prev['value'];
47|            $bps = ($timeDiff > 0 && $valueDiff >= 0) ? ($valueDiff / $timeDiff) : 0;
48|
49|            $points[] = [
50|                'x' => $curr['clock'] * 1000,
51|                'y' => round($bps / 1000000, 2),
52|            ];
53|        }
54|
55|        return $points;
56|    }
57|
58|    public function getItemIdByKey($key)
59|    {
60|        $response = $this->request('item.get', [
61|            'output' => ['itemid'],
62|            'filter' => [
63|                'key_' => $key,
64|            ],
65|        ]);
66|
67|        if (! isset($response['result'][0])) {
68|            return null;
69|        }
70|
71|        return $response['result'][0]['itemid'] ?? null;
72|    }
73|
74|    protected function request($method, $params = [])
75|    {
76|        $response = Http::withHeaders([
77|            'Content-Type' => 'application/json',
78|            'Authorization' => 'Bearer '.$this->auth,
79|        ])->timeout(10)->post($this->url, [
80|            'jsonrpc' => '2.0',
81|            'method' => $method,
82|            'params' => $params,
83|            'id' => 1,
84|        ]);
85|
86|        if ($response->failed()) {
87|            throw new \Exception('Zabbix API HTTP error: '.$response->status());
88|        }
89|
90|        $data = $response->json();
91|        if (! is_array($data)) {
92|            throw new \Exception('Zabbix API returned invalid JSON');
93|        }
94|
95|        if (isset($data['error'])) {
96|            throw new \Exception('Zabbix API error: '.($data['error']['message'] ?? 'unknown'));
97|        }
98|
99|        return $data;
100|    }
101|
102|    /**
103|     * تست اتصال واقعی به Zabbix API — version info بازمی‌گردونه.
104|     *
105|     * @return array{version: string}
106|     *
107|     * @throws \Exception
108|     */
109|    public function testApiConnection(): array
110|    {
111|        $response = $this->request('apiinfo.version', []);
112|
113|        $version = $response['result'] ?? null;
114|
115|        if (! is_string($version)) {
116|            throw new \Exception('Zabbix API returned unexpected version response');
117|        }
118|
119|        return ['version' => $version];
120|    }
121|
122|    public function getLatestValues(array $itemIds): array
123|    {
124|        if (empty($itemIds)) {
125|            return [];
126|        }
127|
128|        $response = $this->request('item.get', [
129|            'output' => ['itemid', 'lastvalue'],
130|            'itemids' => $itemIds,
131|        ]);
132|
133|        $result = [];
134|        foreach ($response['result'] as $item) {
135|            $result[$item['itemid']] = isset($item['lastvalue']) ? (float) $item['lastvalue'] : null;
136|        }
137|
138|        // اطمینان از وجود کلید برای همه آیتم‌های درخواستی
139|        foreach ($itemIds as $id) {
140|            if (! array_key_exists($id, $result)) {
141|                $result[$id] = null;
142|            }
143|        }
144|
145|        return $result;
146|    }
