2|
3|namespace Tests\Feature;
4|
5|use App\Models\Ticket;
6|use App\Models\Todo;
7|use Database\Seeders\PermissionSeeder;
8|use Illuminate\Foundation\Testing\RefreshDatabase;
9|use Illuminate\Support\Facades\Cache;
10|use Livewire\Livewire;
11|use Morilog\Jalali\Jalalian;
12|use Tests\Support\Concerns\InteractsWithTestSetup;
13|use Tests\TestCase;
14|
15|/**
16| * Issue #736 — the UI side of the one-window rule.
17| *
18| * The dashboard ticket trend clipped with `ORDER BY day ASC` + `LIMIT 30`, which
19| * returns the *oldest* 30 days, so recent days were missing from the chart
20| * entirely. The report pages grouped the whole history, so the same chart
21| * looked different depending on where it was rendered.
22| */
23|class ReportsDailyWindowTest extends TestCase
24|{
25|    use InteractsWithTestSetup;
26|    use RefreshDatabase;
27|
28|    protected function setUp(): void
29|    {
30|        parent::setUp();
31|        $this->seed(PermissionSeeder::class);
32|        $this->seedLookupTables();
33|    }
34|
35|    /**
36|     * `created_at` is not fillable on Ticket, so it is set after the insert.
37|     */
38|    protected function createTicketAt($user, string $code, \DateTimeInterface $createdAt): Ticket
39|    {
40|        $ticket = Ticket::create([
41|            'ticket_code' => $code,
42|            'user_id' => $user->id,
43|            'unit_id' => $user->units()->first()->id,
44|            'subject' => 'روند',
45|            'content' => 'متن',
46|            'priority' => 'normal',
47|            'status' => 'created',
48|        ]);
49|
50|        $ticket->forceFill([
51|            'created_at' => $createdAt,
52|            'updated_at' => $createdAt,
53|        ])->saveQuietly();
54|
55|        return $ticket->refresh();
56|    }
57|
58|    public function test_dashboard_ticket_chart_shows_the_most_recent_days_not_the_oldest(): void
59|    {
60|        ['user' => $user] = $this->createUserWithUnit();
61|        $this->actingAs($user);
62|
63|        // 40 distinct days: more than the 30-day window, so a LIMIT applied
64|        // before the ORDER BY would keep the wrong end of the range.
65|        for ($i = 0; $i < 40; $i++) {
66|            $this->createTicketAt($user, 'TREND-'.$i, now()->subDays(39 - $i)->startOfDay()->addHours(9));
67|        }
68|
69|        $data = Livewire::test('dashboard')->instance()->getTicketChartDataProperty();
70|
71|        $this->assertCount(30, $data['categories'], 'the chart is clipped to the 30-day window');
72|        $this->assertSame(30, array_sum($data['series']), 'only 30 of the 40 days are shown');
73|
74|        // The window must END today. With `ORDER BY day ASC` + `LIMIT 30` the
75|        // first category is 10 days ago and the last is 39 days ago — the
76|        // opposite, which is exactly the bug this asserts against.
77|        $today = Jalalian::fromCarbon(now())->format('m/d');
78|        $windowStart = Jalalian::fromCarbon(now()->subDays(29))->format('m/d');
79|
80|        $this->assertSame($today, end($data['categories']), 'the newest day in the chart is today');
81|        $this->assertSame($windowStart, reset($data['categories']), 'the oldest day in the chart is 29 days ago');
82|    }
83|
84|    public function test_dashboard_ticket_chart_keeps_ascending_display_order(): void
85|    {
86|        ['user' => $user] = $this->createUserWithUnit();
87|        $this->actingAs($user);
88|
89|        $this->createTicketAt($user, 'OLD', now()->subDays(5)->startOfDay());
90|        $this->createTicketAt($user, 'NEW', now()->startOfDay());
91|
92|        Cache::flush();
93|        $data = Livewire::test('dashboard')->instance()->getTicketChartDataProperty();
94|
95|        // Exactly the 30 labels of the window, oldest first — the whole
96|        // sequence, so a reversed order or a different window both fail here.
97|        $expected = [];
98|        for ($i = 29; $i >= 0; $i--) {
99|            $expected[] = Jalalian::fromCarbon(now()->subDays($i))->format('m/d');
100|        }
101|
102|        $this->assertSame($expected, $data['categories'], 'oldest first, so the line reads left to right');
103|        $this->assertSame(1, $data['series'][24], 'the 5-days-ago ticket sits in its own slot');
104|        $this->assertSame(1, $data['series'][29], 'today holds the newest ticket');
105|        $this->assertSame(2, array_sum($data['series']));
106|    }
107|
108|    public function test_dashboard_ticket_chart_includes_days_without_tickets_as_zero(): void
109|    {
110|        ['user' => $user] = $this->createUserWithUnit();
111|        $this->actingAs($user);
112|
113|        $this->createTicketAt($user, 'ONE', now()->startOfDay());
114|
115|        Cache::flush();
116|        $data = Livewire::test('dashboard')->instance()->getTicketChartDataProperty();
117|
118|        $this->assertCount(30, $data['categories'], 'every day in the window has a slot');
119|        $this->assertSame(1, array_sum($data['series']), 'only the one real ticket is counted');
120|        $this->assertContains(0, $data['series'], 'a day with no tickets is a zero, not a gap');
121|        $this->assertSame(29, count(array_keys($data['series'], 0, true)), 'the other 29 days are zero');
122|    }
123|
124|    public function test_reports_todos_by_day_fills_empty_days_over_the_chosen_range(): void
125|    {
126|        ['user' => $user] = $this->createUserWithUnit();
127|        $this->actingAs($user);
128|
129|        $from = now()->subDays(6);
130|        $to = now()->addDays(1);
131|
132|        // end_at is set because the page's own "to" filter is `end_at <= to`,
133|        // which excludes todos with no due date.
134|        Todo::create([
135|            'title' => 'یک',
136|            'unit_id' => $user->units()->first()->id,
137|            'is_completed' => false,
138|            'start_at' => now()->startOfDay(),
139|            'end_at' => now()->startOfDay(),
140|        ]);
141|
142|        $component = Livewire::test('reports.todos')
143|            ->set('dateFrom', Jalalian::fromCarbon($from)->format('Y/m/d'))
144|            ->set('dateTo', Jalalian::fromCarbon($to)->format('Y/m/d'));
145|
146|        $byDay = $component->instance()->chartPayload()['byDay'];
147|
148|        $this->assertCount(8, $byDay, 'from..to inclusive is 8 days and all 8 are present');
149|        $this->assertSame(1, array_sum(array_column($byDay, 'count')));
150|        $this->assertSame(7, count(array_filter(array_column($byDay, 'count'), fn ($c) => $c === 0)));
151|    }
152|
153|    public function test_reports_advanced_by_day_fills_empty_days_over_the_chosen_range(): void
154|    {
155|        ['user' => $user] = $this->createUserWithUnit();
156|        $this->actingAs($user);
157|
158|        $this->createTicketAt($user, 'ADV-1', now()->startOfDay());
159|
160|        $from = now()->subDays(4);
161|        $to = now()->subDays(1);
162|
163|        $component = Livewire::test('reports.advanced')
164|            ->set('dateFrom', Jalalian::fromCarbon($from)->format('Y/m/d'))
165|            ->set('dateTo', Jalalian::fromCarbon($to)->format('Y/m/d'));
166|
167|        $byDay = $component->instance()->chartPayload()['byDay'];
168|
169|        $this->assertCount(4, $byDay, 'the 4-day range is fully materialised');
170|        $this->assertSame([0, 0, 0, 0], array_column($byDay, 'count'), 'no tickets in the range at all');
171|    }
