11|use Tests\Support\Concerns\InteractsWithTestSetup;
12|use Tests\TestCase;
13|
14|/**
15| * Regression tests for the `/it/wireless` «Too Many Attempts» (HTTP 429) bug.
16| *
17| * The Zabbix read endpoints sit behind `throttle:api-user`, which allows
18| * 60 requests per minute **per user, across the whole API** — not per page.
19| * `/it/wireless` used to render one `it.multi-gauge` per device, and each gauge
20| * ran its own `fetch('/api/zabbix/multi-latest')` on load and every 30s. Worse,
21| * the gauge's `x-init="init()"` fired *in addition* to Alpine's automatic
22| * `init()` call, so the first load issued two requests per gauge.
23| *
24| * With the 14 seeded wireless devices that is 28 requests/minute steady-state
25| * and 42 in the first minute — over the limit within seconds of page load.
26| *
27| * These tests pin the fix at the layer that actually caused it: the page now
28| * batches every gauge into ONE request per refresh cycle, and the gauge is
29| * presentational only.
30| */
31|class WirelessGaugeRateLimitTest extends TestCase
32|{
33|    use InteractsWithTestSetup;
34|    use RefreshDatabase;
35|
36|    protected function setUp(): void
37|    {
38|        parent::setUp();
39|        $this->seed(PermissionSeeder::class);
40|        $this->seedLookupTables();
41|        $this->seed(ZabbixDeviceSeeder::class);
42|    }
43|
44|    // ==================== Batching contract ====================
45|
46|    public function test_item_ids_cover_every_device_without_duplicates(): void
47|    {
48|        ['user' => $user] = $this->createUserWithUnit(['map']);
49|        $this->actingAs($user);
50|
51|        $ids = Livewire::test('it.wireless')->assertOk()->instance()->itemIds();
52|
53|        // 14 wireless devices × 3 items each.
54|        $this->assertCount(42, $ids);
55|        $this->assertSame(array_unique($ids), $ids, 'itemIds() must not repeat an id.');
56|        $this->assertContains('75297', $ids); // first device's signal item
57|    }
58|
59|    public function test_a_single_request_carries_every_gauge_within_the_endpoint_limit(): void
60|    {
61|        ['user' => $user] = $this->createUserWithUnit(['map']);
62|        $this->actingAs($user);
63|
64|        $ids = Livewire::test('it.wireless')->assertOk()->instance()->itemIds();
65|
66|        // MultiLatestValueController validates `item_ids` as `array|max:100`, so
67|        // one request is only enough while the page fits inside that ceiling.
68|        $this->assertLessThanOrEqual(100, count($ids));
69|    }
70|
71|    public function test_item_ids_is_empty_when_no_wireless_device_exists(): void
72|    {
73|        ['user' => $user] = $this->createUserWithUnit(['map']);
74|        $this->actingAs($user);
75|
76|        ZabbixDevice::query()->where('type', 'wireless')->update(['is_active' => false]);
77|
78|        $component = Livewire::test('it.wireless')->assertOk();
79|
80|        $this->assertSame([], $component->instance()->itemIds());
81|    }
82|
83|    // ==================== The 429 itself ====================
84|
85|    public function test_the_page_issues_one_multi_latest_request_per_cycle(): void
86|    {
87|        // `@script` is not part of the initial render output, so the fetch has
88|        // to be counted in the Blade source.
89|        $source = $this->bladeSource('livewire/it/wireless.blade.php');
90|
91|        // The only `fetch()` on the page is the single batched poller. If a
92|        // per-gauge fetch ever comes back, this count climbs with the device
93|        // count and the page starts 429-ing again.
94|        $this->assertSame(
95|            1,
96|            $this->countEndpointFetches($source),
97|            'The wireless page must call /api/zabbix/multi-latest exactly once per refresh cycle.'
98|        );
99|        $this->assertSame(1, substr_count($source, 'setInterval('));
100|    }
101|
102|    public function test_the_gauge_no_longer_fetches_or_polls_on_its_own(): void
103|    {
104|        $source = $this->bladeSource('livewire/it/multi-gauge.blade.php');
105|
106|        $this->assertStringNotContainsString('/api/zabbix/', $source);
107|        $this->assertStringNotContainsString('setInterval', $source);
108|        $this->assertStringNotContainsString('fetch(', $source);
109|    }
110|
111|    public function test_the_gauge_markup_carries_no_endpoint_of_its_own(): void
112|    {
113|        ['user' => $user] = $this->createUserWithUnit(['map']);
114|        $this->actingAs($user);
115|
116|        // Guards the *rendered* output too, so a future `x-data` that inlines a
117|        // URL cannot slip past a source-only check.
118|        $this->assertStringNotContainsString('/api/zabbix/', Livewire::test('it.wireless')->assertOk()->html());
119|    }
120|
121|    public function test_the_gauge_subscribes_to_the_shared_state_instead(): void
122|    {
123|        $source = $this->bladeSource('livewire/it/multi-gauge.blade.php');
124|
125|        $this->assertStringContainsString('window.zabbixGauges', $source);
126|        $this->assertStringContainsString('state.subscribers', $source);
127|    }
128|
129|    public function test_a_refresh_cycle_stays_inside_the_api_user_budget(): void
130|    {
131|        $source = $this->bladeSource('livewire/it/wireless.blade.php');
132|
133|        // One request now, one 30s later: 2 per minute regardless of how many
134|        // devices exist. The limiter allows 60/min, so the page can no longer
135|        // be the thing that exhausts it.
136|        $this->assertSame(1, $this->countEndpointFetches($source));
137|
138|        $interval = $this->extractIntervalMs($source);
139|        $this->assertNotNull($interval, 'The page must schedule a refresh interval.');
140|        $this->assertLessThanOrEqual(
141|            60,
142|            (int) ceil($interval / 60000),
143|            'Two refreshes per minute must fit inside the 60/min throttle budget.'
144|        );
145|    }
146|
147|    public function test_the_refresh_interval_is_never_tied_to_the_gauge_count(): void
148|    {
149|        ['user' => $user] = $this->createUserWithUnit(['map']);
150|        $this->actingAs($user);
151|
152|        $withAllDevices = count(Livewire::test('it.wireless')->assertOk()->instance()->itemIds());
153|
154|        ZabbixDevice::query()->where('type', 'wireless')->limit(13)->update(['is_active' => false]);
155|        $this->flushZabbixCache();
156|        $withOneDevice = count(Livewire::test('it.wireless')->assertOk()->instance()->itemIds());
157|
158|        $this->assertSame(42, $withAllDevices);
159|        $this->assertSame(3, $withOneDevice);
160|
161|        // One poller for the page either way — the request count is a property
162|        // of the page, not of the number of gauges on screen.
163|        $source = $this->bladeSource('livewire/it/wireless.blade.php');
164|        $this->assertSame(1, $this->countEndpointFetches($source));
165|    }
166|
167|    // ==================== Sibling page shares the same limiter ====================
168|
169|    public function test_the_networks_charts_do_not_poll_faster_than_the_budget_allows(): void
170|    {
171|        $source = $this->bladeSource('livewire/it/network-traffic-chart.blade.php');
172|
173|        $this->assertSame(1, substr_count($source, 'setInterval'));
174|        $this->assertStringNotContainsString('10000', $source);
175|
176|        // 25 seeded networks × 1 request per cycle must stay under 60/min.
177|        preg_match('/setInterval\(\(\) => this\.load\(\), (\d+)\)/', $source, $matches);
178|        $this->assertNotEmpty($matches, 'Could not read the traffic chart poll interval.');
179|
180|        $requestsPerMinute = 25 * (int) ceil((int) $matches[1] / 60000);
181|        $this->assertLessThanOrEqual(60, $requestsPerMinute);
182|    }
183|
184|    // ==================== Helpers ====================
185|
186|    /**
187|     * Read a Blade view with its `{{-- … --}}` comments removed, so assertions
188|     * only ever see executable code and never the prose around it.
189|     */
190|    private function bladeSource(string $view): string
191|    {
192|        $source = file_get_contents(resource_path('views/'.$view));
193|
194|        return (string) preg_replace('/\{\{--.*?--\}\}/s', '', $source);
195|    }
196|
197|    /**
198|     * Count real `fetch()` call sites for the multi-latest endpoint.
199|     *
200|     * Deliberately matches the call, not the bare URL, so a PHPDoc or `//`
201|     * comment that merely *mentions* the endpoint cannot inflate the count.
202|     */
203|    private function countEndpointFetches(string $source): int
204|    {
205|        return preg_match_all('/fetch\(\s*[`\'"]\/api\/zabbix\/multi-latest/', $source);
206|    }
207|
208|    private function flushZabbixCache(): void
209|    {
210|        app(CacheInvalidationServiceInterface::class)->increment(ZabbixDevice::CACHE_NAMESPACE);
211|    }
212|
213|    private function extractIntervalMs(string $source): ?int
214|    {
215|        return preg_match('/REFRESH_MS\s*=\s*(\d+)/', $source, $matches)
216|            ? (int) $matches[1]
217|            : null;
218|    }
