9|use Illuminate\Support\Facades\Cache;
10|use Illuminate\Support\Facades\Log;
11|use Throwable;
12|
13|class MultiLatestValueController extends Controller
14|{
15|    public function index(Request $request, ZabbixClient $zabbix): JsonResponse
16|    {
17|        $request->validate([
18|            'item_ids' => 'required|array|max:100',
19|            'item_ids.*' => 'required|string|max:64',
20|        ]);
21|
22|        $itemIds = $request->item_ids;
23|        sort($itemIds); // مرتب‌سازی برای یکسان بودن کلید کش
24|
25|        $cacheKey = 'multi_latest_'.implode('_', $itemIds);
26|
27|        try {
28|            $values = Cache::get($cacheKey);
29|
30|            if ($values !== null) {
31|                return response()->json($values);
32|            }
33|
34|            // #741: typed transport result. A failure is NOT written to the
35|            // cache — remember() never cached exceptions either, so a broken
36|            // Zabbix must not pin its own error for the TTL.
37|            $result = $zabbix->latestValues($itemIds);
38|
39|            if ($result->failed()) {
40|                Log::error('Zabbix API error', [
41|                    'failure' => $result->failure(),
42|                    'message' => $result->message(),
43|                ]);
44|
45|                return response()->json(['error' => 'Service temporarily unavailable'], 503);
46|            }
47|
48|            $values = $result->data();
49|            Cache::put($cacheKey, $values, 20);
50|
51|            return response()->json($values);
52|        } catch (Throwable $e) {
53|            Log::error('Zabbix API error', ['exception' => $e]);
54|
55|            return response()->json(['error' => 'Service temporarily unavailable'], 503);
56|        }
