3|namespace App\Services\Zabbix;
4|
5|use App\Services\ZabbixService;
6|use Illuminate\Http\Client\ConnectionException;
7|use Throwable;
8|
9|/**
10| * {@see ZabbixClient} over the existing {@see ZabbixService}.
11| *
12| * ZabbixService throws plain exceptions (`Zabbix API HTTP error: …`,
13| * `Zabbix API returned invalid JSON`, cURL failures from Laravel's Http
14| * client). This class is the single place those get classified into the
15| * typed failure kinds, so no controller ever sees an exception from the
16| * transport again.
17| *
18| * It deliberately wraps whatever ZabbixService instance the container gives:
19| * existing tests bind a Mockery mock for `ZabbixService::class` and still
20| * expect their exact calls (`->once()`, `->with(...)`) — the wrapper resolves
21| * the service lazily at call time, so those mocks keep working untouched.
22| */
23|class ServiceZabbixClient implements ZabbixClient
24|{
25|    public function __construct(private readonly ZabbixService $zabbix) {}
26|
27|    public function traffic(int|string $itemId, int $duration = 3600): ZabbixResult
28|    {
29|        try {
30|            return ZabbixResult::success($this->zabbix->getInterfaceTraffic($itemId, $duration));
31|        } catch (Throwable $e) {
32|            return self::from($e);
33|        }
