3|namespace Tests\Feature;
4|
5|use Tests\TestCase;
6|
7|covers(GitHooksTest::class);
8|
9|/*
10| * The hooks are versioned under .githooks/ and activated with core.hooksPath,
11| * because composer's post-install-cmd symlink only appears on a fresh
12| * `composer install`: on an already-provisioned machine the light pre-commit
13| * layer is silently absent, and nobody notices until CI rejects the format.
14| *
15| * Every assertion below runs against the hook's EXECUTABLE lines only —
16| * comments are stripped first. Both hooks explain in prose why they do not run
17| * something (that is the whole strategy, written down where the next person
18| * will read it), and a grep that counted those words would pass a hook that
19| * runs exactly what it promises not to.
20| */
21|class GitHooksTest extends TestCase
22|{
23|    private const HOOKS = ['pre-commit', 'pre-push'];
24|
25|    private function hookPath(string $hook): string
26|    {
27|        return base_path(".githooks/{$hook}");
28|    }
29|
30|    /**
31|     * The hook's commands, with comments and blank lines removed.
32|     */
33|    private function commands(string $hook): string
34|    {
35|        $lines = file($this->hookPath($hook), FILE_IGNORE_NEW_LINES) ?: [];
36|
37|        $commands = array_filter(
38|            array_map(trim(...), $lines),
39|            fn (string $line) => $line !== '' && ! str_starts_with($line, '#')
40|        );
41|
42|        return implode("\n", $commands);
43|    }
44|
45|    public function test_both_hooks_are_versioned(): void
46|    {
47|        foreach (self::HOOKS as $hook) {
48|            $this->assertFileExists($this->hookPath($hook), ".githooks/{$hook} must be committed");
49|        }
50|    }
51|
52|    public function test_both_hooks_are_executable(): void
53|    {
54|        // core.hooksPath only runs files git considers executable; a hook that
55|        // lost its bit during a copy is a hook that silently never fires.
56|        foreach (self::HOOKS as $hook) {
57|            $this->assertTrue(
58|                is_executable($this->hookPath($hook)),
59|                ".githooks/{$hook} must be executable"
60|            );
61|        }
62|    }
63|
64|    public function test_the_pre_commit_hook_runs_pint_on_staged_files_only(): void
65|    {
66|        $commands = $this->commands('pre-commit');
67|
68|        $this->assertMatchesRegularExpression('/\bpint\b/', $commands);
69|        $this->assertStringContainsString('diff --cached', $commands);
70|    }
71|
72|    public function test_the_pre_commit_hook_never_runs_phpstan_or_the_suite(): void
73|    {
74|        // The three-layer strategy rests on the light layer staying light: a
75|        // pre-commit that runs PHPStan or the suite is a hook the team starts
76|        // bypassing with --no-verify, which is worse than no hook.
77|        $commands = $this->commands('pre-commit');
78|
79|        $this->assertStringNotContainsString('phpstan', $commands);
80|        $this->assertStringNotContainsString('artisan test', $commands);
81|        $this->assertStringNotContainsString('pest', $commands);
82|        $this->assertStringNotContainsString('composer test', $commands);
83|    }
84|
85|    public function test_the_pre_push_hook_runs_the_whole_phpstan_analysis(): void
86|    {
87|        // Full analysis, not the staged subset: a staged-only path would be an
88|        // analysis route CI never exercises, so errors that surface only through
89|        // dependencies would never be seen locally.
90|        $commands = $this->commands('pre-push');
91|
92|        $this->assertStringContainsString('phpstan analyse', $commands);
93|        $this->assertStringNotContainsString('phpstan analyse $', $commands);
94|    }
95|
96|    public function test_the_pre_push_hook_never_runs_the_full_suite_unasked(): void
97|    {
98|        // The suite takes minutes; on push that is a push people cancel or
99|        // bypass. Tests are opt-in, named by the developer — never guessed,
100|        // because a heuristic can report green without running the failing test.
101|        $commands = $this->commands('pre-push');
102|
103|        $this->assertStringContainsString('VERIFY_TESTS', $commands);
104|        $this->assertStringNotContainsString('composer verify', $commands);
105|    }
106|
107|    public function test_the_pre_push_hook_runs_the_suite_only_when_explicitly_named(): void
108|    {
109|        // The opt-in branch is the only path to the suite, and it is guarded by
110|        // a non-empty check rather than by counting arguments.
111|        $commands = $this->commands('pre-push');
112|
113|        $this->assertMatchesRegularExpression('/if \[ -n "?\$\{VERIFY_TESTS:\-\}"? \]/', $commands);
114|    }
115|
116|    public function test_the_hooks_ignore_non_php_changes(): void
117|    {
118|        // A markdown-only commit must not pay for a Pint run, and a docs-only
119|        // push must not pay for PHPStan. The pre-commit hook filters with grep
120|        // (it builds an explicit file list); the pre-push hook lets git do it
121|        // with a pathspec, which is the same guarantee without the extra step.
122|        $this->assertStringContainsString('grep', $this->commands('pre-commit'));
123|        $this->assertStringContainsString('.php', $this->commands('pre-commit'));
124|
125|        $this->assertStringContainsString("'*.php'", $this->commands('pre-push'));
126|    }
127|
128|    public function test_the_pre_push_hook_asks_git_which_refs_are_being_pushed(): void
129|    {
130|        // The index is ALWAYS empty when a pre-push hook runs, so a gate built
131|        // on `git diff --cached` reports nothing and silently never runs — the
132|        // gate that looks installed and never fires. git passes the refs on
133|        // stdin; the hook has to read them.
134|        $commands = $this->commands('pre-push');
135|
136|        $this->assertStringNotContainsString('diff --cached', $commands);
137|        $this->assertMatchesRegularExpression('/while read /', $commands);
138|        $this->assertStringContainsString('pushed_php_files', $commands);
139|    }
140|
141|    public function test_the_pre_push_hook_compares_against_the_remote_sha(): void
142|    {
143|        // The decision has to be made about the range actually being pushed, not
144|        // about the working tree — otherwise a docs-only push still pays for
145|        // PHPStan and a code push on an "empty" index skips it.
146|        $commands = $this->commands('pre-push');
147|
148|        $this->assertStringContainsString('..HEAD', $commands);
149|        $this->assertStringContainsString('0000000000000000000000000000000000000000', $commands);
150|    }
